import csv
tid="629b0be5-87d8-548e-97b9-74ee3a313dd4"
d={}
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row['timeseries_id']==tid:
            d[row['timestamp']]=float(row['value'])
def mean_for(day):
    vals=[v for k,v in d.items() if k.startswith(day)]
    return sum(vals)/len(vals), len(vals)
m1,n1=mean_for('2018-07-19')
m2,n2=mean_for('2018-04-23')
